// Phase43's admitted nonrecursive wrappers are distinct structural owners.
// Preserve an exact decoded inventory, never a permissive module-wide count.
const structuralOwners=[...source.matchAll(/function \$R_([0-9_]+)\$tree\(/g)].map(m=>m[1].split('_').map(n=>String.fromCodePoint(Number(n))).join(''));
assert.deepEqual(structuralOwners,['fold.make','fold.share','fold.order.make','benchRecord'],'exact structural owner inventory');
const structuralLine=name=>{const marker='function '+privateName(name)+'$tree(',at=source.indexOf(marker);assert(at>=0);return source.slice(at,source.indexOf('\n',at));};
for(const name of structuralOwners){const body=structuralLine(name);assert(body.includes('/* private structural component */'));report.structure.push({name,kind:name==='fold.make'?'recursive-producer':'nonrecursive-wrapper',sha256:createHash('sha256').update(body).digest('hex')});}
for(const name of ['fold.share','fold.order.make','benchRecord']){const body=structuralLine(name);assert(!body.includes('$visit:for(;;)'),'nonrecursive wrapper '+name);assert.equal(body.split(producerName+'(').length,2,'one producer invocation in '+name);}
assert(/\(\((x\d+),\)=>\(\{\$:"Two",a:\[\1,\1,\]\}\)\)/.test(structuralLine('fold.share')),'private shared child binder preserved');
assert(structuralLine('fold.order.make').includes('({$:"Tip",a:[17,]})'),'private order wrapper retains Tip17');
assert(structuralLine('benchRecord').includes('get(G,"fold.value")'),'private record wrapper retains generic fold residual');
assert(structuralLine('benchRecord').includes('Math.imul(')&&structuralLine('benchRecord').includes('(65599)'),'private record wrapper retains weighted field');
